using System;using System.IO;using System.Linq;using System.Collections;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class AnalysisOverviewTests {
  GameRuntime game;string directory;const string Output="/tmp/idle-analysis-review";
  [UnitySetUp]public IEnumerator Setup(){directory=Path.Combine(Path.GetTempPath(),"analysis-review-"+Guid.NewGuid());Directory.CreateDirectory(directory);Directory.CreateDirectory(Output);GameRuntime.SavePathOverride=Path.Combine(directory,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Data=n.Credits=ScientificNumber.From(1000000);n.Workshop.nodes=new[]{"F02","F03"};n.Story.enabled=false;n.Story.open=null;n.Story.queue=Array.Empty<string>();n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();n.Story.tutorial="skipped";return n;});game.Show("items");game.WorkshopView.ChangeMode("components");yield return null;Debug.Log("PREPARED_ANALYSIS_REVIEW: isolated temporary save, financed resources and F02/F03; no normal save touched");}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;}
  static void Click(string name){var b=GameObject.Find(name)?.GetComponent<Button>();Assert.That(b,Is.Not.Null,name);Assert.That(b.interactable,Is.True,name);b.onClick.Invoke();}
  static void Focus(ScrollRect scroll,RectTransform target,bool bottom=false){Canvas.ForceUpdateCanvases();var corners=new Vector3[4];target.GetWorldCorners(corners);float y=scroll.viewport.InverseTransformPoint(corners[bottom?0:1]).y;float wanted=bottom?scroll.viewport.rect.yMin+8:scroll.viewport.rect.yMax-4;scroll.content.anchoredPosition+=Vector2.up*(wanted-y);}
  [UnityTest]public IEnumerator RealControlsQueuePersistDrainAndReload(){Click("analysis-hardware-short");Assert.That(game.State.Workshop.analysis.units,Is.EqualTo(24));for(int i=0;i<6;i++)Click("analysis-hardware-short");Assert.That(game.State.Industry.analysisQueue.Length,Is.EqualTo(6));Assert.That(GameObject.Find("analysis-hardware-short").GetComponent<Button>().interactable,Is.False);Click("AnalysisQueue2");Assert.That(game.State.Industry.analysisQueue.Length,Is.EqualTo(5));Click("AnalysisRepeat");Assert.That(game.State.Meta.analysisAuto,Is.True);var stored=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(stored.Writable,Is.True,stored.Message);Assert.That(stored.State.Industry.analysisQueue.Length,Is.EqualTo(5));Assert.That(stored.State.Meta.analysisAuto,Is.True);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Industry.analysisQueue.Length,Is.EqualTo(5));Assert.That(game.State.Meta.analysisAuto,Is.True);game.Show("items");game.WorkshopView.ChangeMode("components");yield return null;Click("AnalysisRepeat");game.Act(s=>Game.Advance(s,s.SavedAt+7200000));Assert.That(game.State.Workshop.hasAnalysis,Is.False);Assert.That(game.State.Industry.analysisQueue,Is.Empty);Assert.That(game.State.Industry.lastAnalysisAmounts.Sum(),Is.EqualTo(24));Assert.That(game.State.Lifetime.analysesCompleted,Is.EqualTo(6));double completed=game.State.Lifetime.analysesCompleted;yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Lifetime.analysesCompleted,Is.EqualTo(completed));}
  [UnityTest]public IEnumerator ActualMobileViewsAndNoTickRecreation(){Click("analysis-hardware-short");Click("analysis-hardware-short");Click("AnalysisRepeat");foreach(string lang in new[]{"de","en"})foreach(int width in new[]{320,390,430}){game.Act(s=>SettingsRules.Change(s,"language",lang));PortraitGameView.Set(width,width==320?694:width==390?846:932);yield return null;yield return null;Canvas.ForceUpdateCanvases();var scroll=game.WorkshopView.GetComponentInParent<ScrollRect>();scroll.verticalNormalizedPosition=1;yield return null;WorkshopTests.Capture(width,Screen.height,Output+"/overview-"+lang+"-"+width+".png");var panel=game.WorkshopView.AnalysisPanel;int id=panel.GetInstanceID();var action=GameObject.Find("analysis-hardware-short").GetComponent<Button>();Assert.That(((RectTransform)action.transform).rect.height,Is.GreaterThanOrEqualTo(44));Focus(scroll,(RectTransform)panel.transform);yield return null;WorkshopTests.Capture(width,Screen.height,Output+"/planning-"+lang+"-"+width+".png");yield return new WaitForSecondsRealtime(.1f);Assert.That(game.WorkshopView.AnalysisPanel.GetInstanceID(),Is.EqualTo(id));Assert.That(GameObject.Find("analysis-hardware-short").GetComponent<Button>(),Is.SameAs(action));}game.Act(s=>{var n=s.Copy();n.Meta.analysisAuto=false;n.Industry.analysisQueue=Array.Empty<int>();return Game.Advance(n,n.SavedAt+700000);});yield return null;var sc=game.WorkshopView.GetComponentInParent<ScrollRect>();Focus(sc,(RectTransform)game.WorkshopView.AnalysisPanel.transform.Find("AnalysisReceiptGrid"),true);yield return null;WorkshopTests.Capture(390,846,Output+"/actual-receipt.png");Assert.That(game.State.Industry.lastAnalysisAmounts.Sum(),Is.EqualTo(24));}
 }
}
